-- Structural fixture only. No production records or credentials.
create schema private; create schema auth; create schema extensions; create schema vault;
create role anon; create role authenticated; create role service_role;
create function auth.uid() returns uuid language sql as $$
  select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid $$;
create function auth.role() returns text language sql as $$
  select coalesce(nullif(current_setting('request.jwt.claim.role',true),''),nullif(current_setting('role',true),'none')) $$;
create function public.is_approved_admin() returns boolean language sql as $$
  select coalesce(current_setting('test.admin',true),'false')='true' $$;
create function extensions.pgp_sym_decrypt(bytea,text) returns text language sql as $$ select 'TEST_ONLY'::text $$;
create function extensions.digest(text,text) returns bytea language sql as $$ select decode(md5($1),'hex') $$;
create table vault.decrypted_secrets(name text, decrypted_secret text);
insert into vault.decrypted_secrets values('gate_api_credentials_key','TEST_ONLY');

create table public.copy_system_control (
  "singleton" boolean default true not null,
  "execution_enabled" boolean default false not null,
  "emergency_halted" boolean default true not null,
  "halt_reason" text default 'TRADING_WORKER_NOT_CONFIGURED'::text not null,
  "updated_by" uuid,
  "updated_at" timestamp with time zone default now() not null,
  "max_order_slippage_ratio" numeric default 0.005 not null,
  "broker_channel_id" text default 'maetajak'::text not null,
  constraint "copy_system_control_broker_channel_id_check" CHECK ((broker_channel_id ~ '^[a-z0-9]{1,19}$'::text)),
  constraint "copy_system_control_max_order_slippage_ratio_check" CHECK (((max_order_slippage_ratio >= 0.0001) AND (max_order_slippage_ratio <= 0.03))),
  constraint "copy_system_control_pkey" PRIMARY KEY (singleton),
  constraint "copy_system_control_singleton_check" CHECK (singleton)
);

create table private.trading_accounts (
  "id" uuid default gen_random_uuid() not null,
  "user_id" uuid,
  "credential_user_id" uuid,
  "account_role" text not null,
  "settle" text default 'usdt'::text not null,
  "status" text default 'DISABLED'::text not null,
  "is_primary" boolean default true not null,
  "created_at" timestamp with time zone default now() not null,
  "updated_at" timestamp with time zone default now() not null,
  constraint "trading_accounts_account_role_check" CHECK ((account_role = ANY (ARRAY['MASTER'::text, 'MEMBER'::text]))),
  constraint "trading_accounts_credential_user_id_account_role_settle_key" UNIQUE (credential_user_id, account_role, settle),
  constraint "trading_accounts_pkey" PRIMARY KEY (id),
  constraint "trading_accounts_status_check" CHECK ((status = ANY (ARRAY['ACTIVE'::text, 'DISABLED'::text, 'ERROR'::text, 'HALTED'::text]))),
  constraint "trading_accounts_user_id_account_role_settle_key" UNIQUE (user_id, account_role, settle)
);

create table private.copy_account_snapshots (
  "id" bigint generated by default as identity not null,
