  "source_hash" text not null,
  "created_at" timestamp with time zone default now() not null,
  constraint "copy_account_snapshots_available_equity_check" CHECK ((available_equity >= (0)::numeric)),
  constraint "copy_account_snapshots_pkey" PRIMARY KEY (id),
  constraint "copy_account_snapshots_total_equity_check" CHECK ((total_equity >= (0)::numeric)),
  constraint "copy_account_snapshots_trading_account_id_observed_at_sourc_key" UNIQUE (trading_account_id, observed_at, source_hash)
);

create table private.copy_cycles (
  "id" uuid default gen_random_uuid() not null,
  "master_account_id" uuid not null,
  "master_snapshot_id" bigint,
  "status" text default 'PLANNED'::text not null,
  "source_version" text not null,
  "started_at" timestamp with time zone,
  "completed_at" timestamp with time zone,
  "error_code" text,
  "created_at" timestamp with time zone default now() not null,
  constraint "copy_cycles_master_account_id_source_version_key" UNIQUE (master_account_id, source_version),
