);

create table public.copy_position_states (
  "id" uuid default gen_random_uuid() not null,
  "user_id" uuid not null,
  "trading_account_id" uuid not null,
  "contract" text not null,
  "state" text default 'PAUSED'::text not null,
  "target_size" numeric default 0 not null,
  "actual_size" numeric default 0 not null,
  "delta_size" numeric default 0 not null,
  "previous_actual_size" numeric,
  "unexplained_delta" numeric default 0 not null,
  "copy_ratio" numeric not null,
  "max_position_ratio" numeric not null,
  "drift_tolerance_size" numeric default 1 not null,
  "manual_override_confirmed_at" timestamp with time zone,
  "pause_reason" text,
  "last_cycle_id" uuid,
  "last_observed_at" timestamp with time zone,
  "updated_at" timestamp with time zone default now() not null,
  "position_side" text default 'LONG'::text not null,
  "target_leverage" numeric,
  "margin_mode" text,
  "position_mode" text,
  constraint "copy_position_states_account_contract_side_key" UNIQUE (trading_account_id, contract, position_side),
  constraint "copy_position_states_drift_tolerance_size_check" CHECK ((drift_tolerance_size >= (0)::numeric)),
  constraint "copy_position_states_pkey" PRIMARY KEY (id),
  constraint "copy_position_states_position_side_check" CHECK ((position_side = ANY (ARRAY['LONG'::text, 'SHORT'::text]))),
  constraint "copy_position_states_state_check" CHECK ((state = ANY (ARRAY['SYNCED'::text, 'DRIFT'::text, 'MANUAL_OVERRIDE'::text, 'PAUSED'::text, 'REDUCE_ONLY'::text, 'ERROR'::text, 'HALTED'::text])))
);

create table public.copy_events (
  "id" bigint generated by default as identity not null,
  "user_id" uuid,
  "contract" text,
  "event_type" text not null,
  "severity" text default 'INFO'::text not null,
  "cycle_id" uuid,
  "safe_payload" jsonb default '{}'::jsonb not null,
  "occurred_at" timestamp with time zone default now() not null,
  "position_side" text,
  constraint "copy_events_event_type_check" CHECK ((event_type = ANY (ARRAY['MASTER_POSITION_CHANGED'::text, 'TARGET_POSITION_CALCULATED'::text, 'DELTA_ORDER_PLANNED'::text, 'ORDER_SUBMITTED'::text, 'ORDER_FILLED'::text, 'ORDER_UNKNOWN'::text, 'POSITION_SYNCED'::text, 'MANUAL_OVERRIDE_DETECTED'::text, 'SYMBOL_PAUSED'::text, 'RISK_REDUCE_ONLY'::text, 'MEMBER_HALTED'::text, 'SYSTEM_HALTED'::text, 'ERROR'::text]))),
  constraint "copy_events_pkey" PRIMARY KEY (id),
  constraint "copy_events_position_side_check" CHECK (((position_side IS NULL) OR (position_side = ANY (ARRAY['LONG'::text, 'SHORT'::text])))),
  constraint "copy_events_severity_check" CHECK ((severity = ANY (ARRAY['INFO'::text, 'WARNING'::text, 'CRITICAL'::text])))
);

