create table public.profiles (
  "id" uuid not null,
  "email" text not null,
  "full_name" text default ''::text not null,
  "phone" text default ''::text not null,
  "role" text default 'MEMBER'::text not null,
  "approval_status" text default 'PENDING'::text not null,
  "terms_accepted_at" timestamp with time zone,
  "approved_at" timestamp with time zone,
  "approved_by" uuid,
  "created_at" timestamp with time zone default now() not null,
  "updated_at" timestamp with time zone default now() not null,
  "copy_ratio" numeric default 100 not null,
  "max_position_ratio" numeric default 30 not null,
  "terms_version" text,
  "privacy_version" text,
  "copy_started_at" timestamp with time zone,
  "copy_paused" boolean default false not null,
  "member_halted" boolean default false not null,
  "reduce_only" boolean default false not null,
  "daily_loss_limit_pct" numeric default 5 not null,
  "max_drawdown_pct" numeric default 15 not null,
  "max_leverage" numeric default 10 not null,
  "close_positions_requested" boolean default false not null,
  "nickname" text,
  constraint "profiles_approval_status_check" CHECK ((approval_status = ANY (ARRAY['PENDING'::text, 'APPROVED'::text, 'REJECTED'::text, 'SUSPENDED'::text]))),
  constraint "profiles_copy_ratio_check" CHECK ((((copy_ratio >= (50)::numeric) AND (copy_ratio <= (200)::numeric)) AND (mod(copy_ratio, (10)::numeric) = (0)::numeric))),
  constraint "profiles_daily_loss_limit_pct_check" CHECK (((daily_loss_limit_pct >= 0.1) AND (daily_loss_limit_pct <= (100)::numeric))),
  constraint "profiles_max_drawdown_pct_check" CHECK (((max_drawdown_pct >= 0.1) AND (max_drawdown_pct <= (100)::numeric))),
  constraint "profiles_max_leverage_check" CHECK (((max_leverage >= (1)::numeric) AND (max_leverage <= (100)::numeric))),
  constraint "profiles_max_position_ratio_check" CHECK ((((max_position_ratio >= (20)::numeric) AND (max_position_ratio <= (50)::numeric)) AND (mod(max_position_ratio, (10)::numeric) = (0)::numeric))),
  constraint "profiles_nickname_length_check" CHECK (((nickname IS NULL) OR ((char_length(TRIM(BOTH FROM nickname)) >= 2) AND (char_length(TRIM(BOTH FROM nickname)) <= 20)))),
  constraint "profiles_pkey" PRIMARY KEY (id),
  constraint "profiles_role_check" CHECK ((role = ANY (ARRAY['MEMBER'::text, 'ADMIN'::text])))
);

